#!/bin/bash
set -e
echo "===================================================================="
echo "🚀 UNPACKING DARA M1 AUTONOMOUS (2000 USC) TARBALL FROM EMBEDDED PAYLOAD"
echo "===================================================================="

cat << DARA_EOF | base64 -d > dara_m1_autonomous_2000usc.tar.gz

DARA_EOF

echo "✅ Saved dara_m1_autonomous_2000usc.tar.gz ($(wc -c < dara_m1_autonomous_2000usc.tar.gz) bytes)"
tar -tzf dara_m1_autonomous_2000usc.tar.gz > /dev/null && echo "✅ Tar archive integrity verified 100%!"
tar -xzvf dara_m1_autonomous_2000usc.tar.gz
echo "🎉 ALL FILES REPLACED AND READY FOR BUILD & PM2 RESTART!"
